import React, { useState, createContext, useEffect } from 'react';
import { Search, ShoppingCart, CheckCircle2, Sparkles, User, Heart, Filter, Package, TrendingUp, Bell, ArrowRight, MoreHorizontal, Zap, Mail, Home, BarChart3, Star } from 'lucide-react';

const initialCart = [
  { id: '001', name: 'Ethiopian Yirgacheffe', price: 25.99, quantity: 3 },
  { id: '002', name: 'Sumatran Mandheling', price: 32.45, quantity: 1 },
];

const initialProducts = [
  { id: '001', name: 'Ethiopian Yirgacheffe', category: 'African', price: 25.99, rating: 4.8, stock: 14 },
  { id: '002', name: 'Sumatran Mandheling', category: 'Asian', price: 32.45, rating: 4.7, stock: 6 },
  { id: '003', name: 'Kona Peaberry', category: 'Pacific', price: 45.00, rating: 4.9, stock: 5 },
  { id: '004', name: 'Guatemalan Antigua', category: 'Central American', price: 38.99, rating: 4.6, stock: 10 },
];

const initialSubscriptions = [
  { id: '1', title: 'Monthly Taster Box', price: 49.99, interval: 'Monthly', perks: ['Free shipping', '10% off'] },
  { id: '2', title: 'Gourmet Box', price: 89.99, interval: 'Bi-weekly', perks: ['Exclusive single origins', '15% off'] },
];

const initialReviews = [
  { id: '1', name: 'Samantha R.', date: '2 weeks ago', rating: 5, text: 'The coffee is consistently delicious and the delivery is super fast!' },
  { id: '2', name: 'Carlos V.', date: '1 month ago', rating: 4.5, text: 'Love the variety of beans. A bit pricey but the quality is unmatched.' },
];

const GlobalContext = createContext();

export default function App() {
  const [cart, setCart] = useState(initialCart);
  const [products, setProducts] = useState(initialProducts);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [newItem, setNewItem] = useState({ id: '', name: '', price: 0, quantity: 1 });
  const [showToast, setShowToast] = useState(false);
  const [activeTab, setActiveTab] = useState('catalog');
  const [currentSubscription, setCurrentSubscription] = useState(null);
  const [reviews, setReviews] = useState(initialReviews);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);

  useEffect(() => {
    const savedCart = localStorage.getItem('ecommerceStoreCart');
    if (savedCart) setCart(JSON.parse(savedCart));
  }, []);

  useEffect(() => {
    localStorage.setItem('ecommerceStoreCart', JSON.stringify(cart));
  }, [cart]);

  const handleAddToCart = (product) => {
    const existing = cart.find(item => item.id === product.id);
    if (existing) {
      setCart(cart.map(item => 
        item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
      ));
    } else {
      setCart([...cart, { ...product, quantity: 1 }]);
    }
    setShowToast(true);
    setTimeout(() => setShowToast(false), 1500);
  };

  const handleRemoveFromCart = (id) => {
    setCart(cart.filter(item => item.id !== id));
  };

  const handleClearCart = () => {
    setCart([]);
  };

  const handleToggleSubscription = (plan) => {
    setCurrentSubscription(plan);
    setIsCheckoutOpen(true);
  };

  const handleReviewSubmit = (rating, text) => {
    setReviews([...reviews, { id: Date.now().toString(), name: 'Anonymous', date: 'Just now', rating, text }]);
  };

  const handleSearch = (e) => {
    setSearchTerm(e.target.value);
  };

  const filteredProducts = products.filter(item =>
    item.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalCartValue = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  return (
    <GlobalContext.Provider value={{
      cart,
      products,
      searchTerm,
      isAddOpen,
      setIsAddOpen,
      newItem,
      setNewItem,
      showToast,
      activeTab,
      setActiveTab,
      currentSubscription,
      setCurrentSubscription,
      isCheckoutOpen,
      setIsCheckoutOpen,
      handleAddToCart,
      handleRemoveFromCart,
      handleClearCart,
      handleToggleSubscription,
      handleSearch,
      handleReviewSubmit,
      filteredProducts,
      totalCartValue,
    }}>
      <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col">
        {/* Header */}
        <header className="py-8 flex items-center justify-between mx-auto max-w-7xl px-6">
          <div className="flex items-center space-x-3">
            <div className="p-3 rounded-xl bg-white/5 border border-white/10">
              <Sparkles className="w-6 h-6 text-indigo-400" />
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight text-slate-100">EcommerceStore</h1>
              <p className="text-slate-400 text-sm">Specialty Coffee Beans</p>
            </div>
          </div>
          <div className="flex items-center space-x-4">
            <div className="p-2 rounded-xl bg-white/5 border border-white/10">
              <Search className="w-5 h-5 text-slate-400" />
            </div>
            <div className="relative inline-flex items-center rounded-xl bg-white/5 border border-white/10 px-3 py-2 text-slate-400 transition-all duration-200 hover:bg-white/10">
              <input 
                type="text" 
                placeholder="Search beans, roasts"
                className="bg-transparent outline-none text-sm placeholder:text-slate-500" 
                onChange={handleSearch}
              />
              <button className="absolute inset-y-0 right-2 flex items-center justify-center px-1.5 text-xs font-medium text-slate-500">
                <Filter className="w-3.5 h-3.5" />
              </button>
            </div>
            <div className="relative inline-flex items-center rounded-xl bg-white/5 border border-white/10 px-3 py-2 text-slate-400 transition-all duration-200 hover:bg-white/10">
              <button onClick={() => setIsAddOpen(true)}>
                <ShoppingCart className="w-5 h-5 text-slate-400" />
                {cart.length > 0 && (
                  <span className="absolute top-1 right-1.5 w-5 h-5 flex items-center justify-center bg-amber-500/20 text-amber-400 rounded-full text-xs font-bold">
                    {cart.length}
                  </span>
                )}
              </button>
            </div>
            {currentSubscription ? (
              <div className="relative inline-flex items-center rounded-xl bg-white/5 border border-white/10 px-3 py-2 text-slate-400 transition-all duration-200 hover:bg-white/10">
                <div className="flex items-center space-x-1.5">
                  <div className="p-1 rounded-xl bg-amber-500/10 text-amber-400 border border-amber-500/20">
                    <Zap className="w-3.5 h-3.5" />
                  </div>
                  <span>{currentSubscription.title} ({currentSubscription.interval})</span>
                </div>
                <button className="absolute inset-y-0 right-0 flex items-center justify-center px-1.5 text-xs font-medium text-slate-500 hover:text-white">
                  <ArrowRight className="w-3.5 h-3.5" />
                </button>
              </div>
            ) : (
              <div className="relative inline-flex items-center rounded-xl bg-white/5 border border-white/10 px-3 py-2 text-slate-400 transition-all duration-200 hover:bg-white/10">
                <button onClick={handleToggleSubscription}>
                  <span className="hidden md:inline">Subscribe & Save</span>
                  <span className="inline md:hidden flex items-center gap-1">
                    <Sparkles className="w-3.5 h-3.5" />
                    <span>Subscribe</span>
                  </span>
                </button>
              </div>
            )}
          </div>
        </header>

        {/* Main Content */}
        <main className="flex-1 p-6 sm:p-8 max-w-7xl mx-auto">
          <div className="w-full max-w-2xl mx-auto">
            {/* Tab Nav */}
            <div className="mb-8">
              <ul className="flex flex-wrap gap-4 justify-center">
                <li>
                  <button 
                    onClick={() => setActiveTab('catalog')}
                    className={`py-3 px-6 rounded-xl font-medium shadow-lg transition-all duration-300 ${
                      activeTab === 'catalog' ? 'bg-white/5 text-slate-100 border border-white/20' : 'text-slate-400 hover:text-slate-200'
                    }`}
                  >
                    Catalog
                  </button>
                </li>
                <li>
                  <button 
                    onClick={() => setActiveTab('reviews')}
                    className={`py-3 px-6 rounded-xl font-medium shadow-lg transition-all duration-300 ${
                      activeTab === 'reviews' ? 'bg-white/5 text-slate-100 border border-white/20' : 'text-slate-400 hover:text-slate-200'
                    }`}
                  >
                    Reviews ({reviews.length})
                  </button>
                </li>
                <li>
                  <button 
                    onClick={() => setActiveTab('subscriptions')}
                    className={`py-3 px-6 rounded-xl font-medium shadow-lg transition-all duration-300 ${
                      activeTab === 'subscriptions' ? 'bg-white/5 text-slate-100 border border-white/20' : 'text-slate-400 hover:text-slate-200'
                    }`}
                  >
                    Subscriptions
                  </button>
                </li>
              </ul>
            </div>

            {/* Active Tab Content */}
            {activeTab === 'catalog' && (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredProducts.map((item) => (
                  <ProductCard 
                    key={item.id} 
                    id={item.id} 
                    name={item.name} 
                    category={item.category} 
                    price={item.price} 
                    rating={item.rating} 
                    stock={item.stock}
                    onAddToCart={handleAddToCart}
                  />
                ))}
              </div>
            )}

            {activeTab === 'reviews' && (
              <div className="py-8">
                {reviews.length ? (
                  <div className="max-w-3xl mx-auto">
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
                      {reviews.map((review) => (
                        <div 
                          key={review.id} 
                          className="bg-white/10 p-6 rounded-xl border border-white/10 hover:scale-[1.02] transition-transform duration-200 hover:border-white/20"
                        >
                          <div className="flex items-center justify-between mb-4">
                            <div className="flex items-center space-x-2">
                              <div className="p-2 rounded-xl bg-emerald-500/20 text-emerald-400 border border-emerald-500/20">
                                <Heart className="w-5 h-5" />
                              </div>
                              <span>{review.name} (Coffee Enthusiast)</span>
                            </div>
                            <span className="text-slate-400 text-sm">{review.date}</span>
                          </div>
                          <div className="flex items-center justify-between mb-4">
                            {[1, 2, 3, 4, 5].map((star) => (
                              <span key={star} className="w-3 h-3 rounded-full bg-amber-500/20 text-amber-400 flex items-center justify-center">
                                <Star className="w-1.5 h-1.5" />
                              </span>
                            ))}
                          </div>
                          <p className="text-slate-400 text-sm">{review.text}</p>
                        </div>
                      ))}
                    </div>
                    <button 
                      onClick={() => setIsAddOpen(true)}
                      className="self-start w-full max-w-sm mx-auto mt-8 bg-amber-500/10 hover:bg-amber-500/20 text-amber-400 border border-amber-500/20 rounded-xl py-3 text-center font-medium shadow-lg transition-all duration-300 hover:shadow-2xl"
                    >
                      Share your review
                    </button>
                  </div>
                ) : (
                  <div className="w-full h-96 flex items-center justify-center bg-white/5 rounded-xl border border-white/10">
                    <p className="text-slate-400 text-center text-sm">No reviews yet. Be the first to leave feedback!</p>
                  </div>
                )}
              </div>
            )}

            {activeTab === 'subscriptions' && (
              <div className="py-8">
                {initialSubscriptions.map((plan) => (
                  <div 
                    key={plan.id} 
                    className="w-full max-w-sm mx-auto bg-white/10 rounded-xl border border-white/10 p-6 shadow-lg transition-transform hover:scale-[1.02] hover:shadow-2xl duration-300"
                  >
                    <div className="flex justify-between mb-6">
                      <h2 className="text-lg font-semibold text-slate-100">{plan.title}</h2>
                      <div className="flex items-center space-x-2">
                        {plan.perks.map((perk) => (
                          <div key={perk} className="bg-white/20 px-3 py-1 rounded-full text-xs font-semibold text-slate-400 border border-white/20">
                            {perk}
                          </div>
                        ))}
                      </div>
                    </div>
                    <div className="py-4">
                      <div className="text-4xl font-bold text-amber-400">$ {plan.price}</div>
                      <div className="text-slate-400 text-sm mt-1">per {plan.interval}</div>
                    </div>
                    <button
                      onClick={() => handleToggleSubscription(plan)}
                      disabled={currentSubscription?.id === plan.id}
                      className="w-full mt-6 bg-amber-500/10 hover:bg-amber-500/20 text-amber-400 border border-amber-500/20 rounded-xl py-3 text-center font-medium shadow-lg transition-all duration-300 hover:shadow-2xl"
                    >
                      {currentSubscription?.id === plan.id ? 'Active' : 'Select'}
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </main>

        {/* Cart Modal */}
        <CartModal 
          isOpen={isCheckoutOpen}
          onClose={() => setIsCheckoutOpen(false)}
          cart={cart}
          total={totalCartValue}
          onCheckout={() => setIsCheckoutOpen(false)}
        />

        {/* Global Modal backdrop */}
        <div className="fixed inset-0 z-50 bg-black/30 backdrop-blur-md animate-fade-in" onClick={() => setIsAddOpen(false)} />

        {/* Add New Item Modal */}
        <div className="fixed inset-0 z-55 w-full max-w-md mx-auto p-6 bg-slate-900 rounded-2xl border border-white/10 shadow-2xl animate-fade-in">
          <div className="text-center mb-8">
            <h2 className="text-xl font-bold tracking-tight text-slate-100">Add New Item</h2>
            <p className="text-slate-400 text-sm mt-2">Quickly add a new premium coffee bean or subscription plan.</p>
          </div>
          <form className="space-y-4">
            <div className="grid grid-cols-2 gap-3">
              <div className="relative">
                <input 
                  type="text" 
                  placeholder="Product name or title"
                  className="w-full bg-white/5 border border-white/10 text-slate-300 placeholder:text-slate-500 rounded-xl py-3 pl-8 pr-4 text-sm outline-none transition-all duration-200 focus:ring-2 focus:ring-indigo-500/30"
                  onChange={(e) => setNewItem({ ...newItem, name: e.target.value })}
                />
                <label htmlFor="new-name" className="absolute left-3 top-3 text-slate-400 text-sm pointer-events-none">Name</label>
              </div>
              {activeTab === 'catalog' && (
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="Category (African, Asian, etc.)"
                    className="w-full bg-white/5 border border-white/10 text-slate-300 placeholder:text-slate-500 rounded-xl py-3 pl-8 pr-4 text-sm outline-none transition-all duration-200 focus:ring-2 focus:ring-indigo-500/30"
                    onChange={(e) => setNewItem({ ...newItem, category: e.target.value })}
                  />
                  <label htmlFor="new-category" className="absolute left-3 top-3 text-slate-400 text-sm pointer-events-none">Category</label>
                </div>
              )}
            </div>
            <div className="relative">
              <input 
                type="number" 
                placeholder="Price ($)"
                className="w-full bg-white/5 border border-white/10 text-slate-300 placeholder:text-slate-500 rounded-xl py-3 pl-8 pr-4 text-sm outline-none transition-all duration-200 focus:ring-2 focus:ring-indigo-500/30"
                onChange={(e) => setNewItem({ ...newItem, price: e.target.valueAsNumber })}
              />
              <label htmlFor="new-price" className="absolute left-3 top-3 text-slate-400 text-sm pointer-events-none">Price</label>
            </div>
            <button 
              type="submit"
              onClick={(e) => {
                e.preventDefault();
                if (activeTab === 'catalog') {
                  const newProduct = {
                    id: Date.now().toString(),
                    ...newItem,
                    stock: 20,
                    rating: 4.9
                  };
                  setProducts([...products, newProduct]);
                  setNewItem({ id: '', name: '', price: 0 });
                } else {
                  const newSubscription = {
                    id: Date.now().toString(),
                    ...newItem,
                    perks: ['Free Shipping', '10% Off'],
                    interval: 'Monthly'
                  };
                  setSubscriptions([...initialSubscriptions, newSubscription]);
                  setNewItem({ id: '', name: '', price: 0 });
                }
                setIsAddOpen(false);
              }}
              className="w-full bg-amber-500/10 hover:bg-amber-500/20 text-amber-400 border border-amber-500/20 rounded-xl py-3 text-center font-medium shadow-lg transition-all duration-300 hover:shadow-2xl"
            >
              {activeTab === 'catalog' ? 'Add Product' : 'Create Plan'}
            </button>
          </form>
        </div>

        {/* Notification Toast */}
        {showToast && (
          <div className="fixed top-6 right-6 z-60 flex items-center gap-2 p-3 rounded-2xl bg-white/10 border border-white/20 backdrop-blur-md animate-slide-in text-sm text-slate-400">
            <CheckCircle2 className="w-5 h-5 text-emerald-400" />
            <div>
              <p className="font-semibold">Item added to cart!</p>
              <p className="text-slate-500">Your selections are ready for checkout.</p>
            </div>
            <span className="inline-flex items-center gap-1 text-xs font-medium text-white bg-rose-500/20 px-2 py-1 rounded-full">
              <span>{cart.length}</span>
              <span>items</span>
            </span>
          </div>
        )}
      </div>
    </GlobalContext.Provider>
  );
}

