import React, { useState } from 'react';
import { CheckCircle2, Heart, Sparkles, Package, Star, ShoppingBag, User, MapPin, Calendar, Sparkle, Sparkles as SparklesIcon } from 'lucide-react';

const PRODUCTS = [
  {
    id: 'coffee-1',
    name: 'Ethiopian Yirgacheffe',
    brand: 'Abyss Valley',
    price: 32.99,
    discount: 0,
    rating: 4.9,
    reviews: 158,
    stock: 18,
    description: 'Ripe cherries from the Yirgacheffe region. Notes of jasmine and bergamot.',
    category: 'Single-Origin',
    image: 'https://images.unsplash.com/photo-1536762786121-8d39f3a7b0b8?w=800&q=80&fm=webp',
    tags: ['organic', 'fair-trade'],
    location: 'Ethiopia',
    roast: 'Light',
    caffeine: '110mg',
    volume: '400g',
  },
  {
    id: 'coffee-2',
    name: 'Colombian Supremo',
    brand: 'Café del Grado',
    price: 28.50,
    discount: 5,
    rating: 4.7,
    reviews: 124,
    stock: 32,
    description: 'Smooth body with hints of caramel and chocolate. Grown in the Cauca Valley.',
    category: 'Supremo',
    image: 'https://images.unsplash.com/photo-1518483826571-5f26e8f82b9f?w=800&q=80&fm=webp',
    tags: ['shade-grown', 'sustainable'],
    location: 'Cauca, Colombia',
    roast: 'Medium',
    caffeine: '130mg',
    volume: '400g',
  },
  {
    id: 'coffee-3',
    name: 'Guatemalan Antigua',
    brand: 'Altura Farms',
    price: 34.00,
    discount: 10,
    rating: 4.9,
    reviews: 182,
    stock: 12,
    description: 'Rich aroma with a full-bodied profile. Grown at high altitudes for exceptional flavor.',
    category: 'Supremo',
    image: 'https://images.unsplash.com/photo-1542089905-4c1f3a7d5995?w=800&q=80&fm=webp',
    tags: ['organic', 'fair-trade'],
    location: 'Antigua, Guatemala',
    roast: 'Dark',
    caffeine: '150mg',
    volume: '400g',
  },
];

export default function ProductCard({ product }) {
  const [isHovered, setIsHovered] = useState(false);
  const [isAddedToCart, setIsAddedToCart] = useState(false);

  const handleHover = () => setIsHovered(true);
  const handleUnhover = () => setIsHovered(false);

  const handleAddToCart = () => {
    setIsAddedToCart(true);
    setTimeout(() => setIsAddedToCart(false), 1500);
  };

  return (
    <div className="group relative w-full max-w-sm rounded-2xl bg-slate-900/50 backdrop-blur-xl border border-white/10 p-6 transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl hover:bg-white/10">
      {/* Background Gradient Decorative Stripe */}
      <div className="absolute -top-1 -right-1 -left-1 -bottom-1 bg-white/5 backdrop-blur-xl rounded-2xl" />

      {/* Card Header */}
      <div className="flex flex-col justify-between space-y-2">
        {/* Top Gradient Decorative Stripe */}
        <div className="absolute -top-1 -right-1 -left-1 -bottom-1 bg-indigo-500/10 backdrop-blur-xl rounded-2xl" />

        {/* Product Image */}
        <div className="relative h-48 w-full overflow-hidden rounded-xl bg-slate-900/50 backdrop-blur-xl transition-all duration-300 group-hover:scale-[1.02]">
          <img
            src={product.image}
            alt={product.name}
            className="h-full w-full object-cover transition-all duration-300 group-hover:scale-[1.05]"
          />
          {/* Glowing Sparkle Effect */}
          <div className="absolute -top-4 -right-4 -bottom-4 -left-4 rounded-xl bg-white/10 backdrop-blur-xl border border-white/20 p-4 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
        </div>

        {/* Badge Stack */}
        <div className="flex flex-wrap items-center justify-center gap-1 text-xs font-medium">
          {product.tags.map(tag => (
            <span key={tag} className="bg-amber-500/10 text-amber-400 px-3 py-1 rounded-full border border-amber-500/20">
              {tag}
            </span>
          ))}
        </div>
      </div>

      {/* Card Body */}
      <div className="mt-6 flex flex-col space-y-3 text-left">
        {/* Title & Brand */}
        <div className="flex flex-col justify-between">
          <div className="flex items-start justify-between">
            <h3 className="text-lg font-semibold text-slate-100">{product.name}</h3>
            <div className="flex items-center gap-1">
              {[1, 2, 3, 4, 5].map((i) => (
                <Star
                  key={i}
                  className="text-amber-400 transition-colors duration-300 hover:text-amber-500"
                  size={18}
                  active={i <= Math.floor(product.rating)}
                />
              ))}
            </div>
          </div>
          <p className="text-sm text-slate-400">{product.location}</p>
        </div>

        {/* Price & Discount */}
        <div className="flex flex-col justify-between">
          <span className="text-xl font-bold text-white">{`$${product.price.toFixed(2)}`}</span>
          {product.discount > 0 && (
            <span className="text-sm font-medium text-slate-500 line-through opacity-50">{`$${(product.price * (1 + product.discount / 100)).toFixed(2)}`}</span>
          )}
        </div>

        {/* Rating & Stock */}
        <div className="flex items-center gap-2 text-sm text-slate-400">
          <Sparkles className="w-3.5 h-3.5 text-amber-400" />
          <span>{product.rating.toFixed(1)}</span>
          <span>({product.reviews} {product.reviews === 1 ? 'Review' : 'Reviews'})</span>
          <span className="ml-auto text-slate-500">{`Stock: ${product.stock} ${product.stock === 1 ? 'Unit' : 'Units'}`}</span>
        </div>
      </div>

      {/* Actions & Add to Cart */}
      <div className="absolute bottom-6 left-6 right-6 flex flex-col items-start gap-2">
        <div className="flex items-center gap-1">
          {[1, 2, 3, 4, 5].map((i) => (
            <Star
              key={i}
              className="text-amber-400 transition-colors duration-300 hover:text-amber-500"
              size={18}
              active={i <= Math.floor(product.rating)}
            />
          ))}
        </div>
        <button
          onClick={handleAddToCart}
          disabled={isAddedToCart || !product.stock}
          className="group flex items-center gap-2 rounded-lg bg-white/5 px-4 py-2 text-sm font-medium text-slate-300 hover:bg-white/10 transition-colors active:scale-95 disabled:opacity-50"
        >
          {isAddedToCart ? (
            <CheckCircle2 className="w-4 h-4 text-emerald-400 group-hover:text-emerald-300" />
          ) : (
            <>
              <ShoppingBag className="w-4 h-4 text-amber-400 group-hover:text-amber-300" />
              <span>{isAddedToCart ? 'Added' : 'Add to Cart'}</span>
            </>
          )}
        </button>
      </div>

      {/* Hover States & Glowing Glow */}
      <div
        onMouseEnter={handleHover}
        onMouseLeave={handleUnhover}
        className="absolute -bottom-1 -left-1 -right-1 -top-1 rounded-xl bg-white/10 backdrop-blur-xl border border-white/20 p-2 transition-all duration-300 group-hover:scale-[1.04]"
      />
    </div>
  );
}

